if dup:
    raise SystemExit(f'⚠️ §3.129d 标题前 24 字重复: {dup}')
amb = [(a, b) for a in pref for b in pref if a != b and b.startswith(a)]
if amb:
    raise SystemExit(f'⚠️ §3.129d 前缀互为前缀: {amb}')
print('✅ 规则表前缀唯一性自检通过')

